// voice clips may be served from another origin (R2); '' = same origin as the site
const CDN = "https://voice.bevui.id.vn/vi/";

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(SHELL).then((c) => c.addAll(FILES)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (e) => {
  e.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => (k.startsWith('bvkp-shell-') && k !== SHELL) || (k.startsWith('bvkp-voice') && k !== VOICE)).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

const isCdn = (url) => !!CDN && url.href.startsWith(CDN);
const isVoice = (url) => url.pathname.endsWith('.mp3') && (isCdn(url) || url.pathname.includes('/voice/vi/'));

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin && !isCdn(url)) return;
  if (req.mode === 'navigate') {
    e.respondWith(fetch(req).catch(() => caches.match('index.html', { ignoreSearch: true })));
    return;
  }
  if (/voice\/vi\/(index|manifest)\.json$/.test(url.pathname)) { // (backslashes doubled: this is inside a template literal)
    // network-first: the index changes when new clips are recorded
    e.respondWith(
      fetch(req)
        .then((res) => {
          const copy = res.clone();
          caches.open(SHELL).then((c) => c.put(req, copy));
          return res;
        })
        .catch(() => caches.match(req)),
    );
    return;
  }
  e.respondWith(
    caches.match(req, { ignoreSearch: true }).then(
      (hit) =>
        hit ||
        fetch(req).then((res) => {
          if (res.ok && isVoice(url)) {
            const copy = res.clone();
            caches.open(VOICE).then((c) => c.put(req, copy));
          }
          return res;
        }),
    ),
  );
});
